export const SKILL_PROFILES = Object.fromEntries(rows.trim().split('\n').map((row) => {
  const [id, topics, ...capabilities] = row.split('~');
  if (!id || !topics || capabilities.length !== 6 || capabilities.some(x => !x.trim())) throw Error('Invalid skill profile: ' + id);
  return [id, {specialties: topics.split(';'), capabilities}];
}));
